#!/usr/bin/env python3
import hashlib,json,re,struct
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'docs/research'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=D/'dedup-model-bank-coverage-native-20261011.json';r=json.loads(p.read_text());assert r['status']=='complete_bounded_real_cpu_model_bank_search' and r['returncode']==0;pins=dict(r['pins']);assert all(sha(k)==v for k,v in pins.items());assert r['plan']['baseline_index']==67;assert sha(r['log'])==r['log_sha256'];assert Path(r['log']).read_text()==r['stdout']+r['stderr'];pins[r['log']]=r['log_sha256']
 mp=D/'dedup-model-bank-coverage-native-snapshot-20261011.json';m=json.loads(mp.read_text());assert all(sha(Path(m['snapshot'])/k)==v for k,v in m['file_hashes'].items());gp=D/'dedup-model-bank-coverage-verification-20261011.json';g=json.loads(gp.read_text());assert g['status']=='verified_101_tests_bounded_pixel_window_coverage';assert all(sha(k)==v for k,v in g['pins'].items());gm=json.loads((D/'dedup-model-bank-coverage-snapshot-20261011.json').read_text());assert all(m['file_hashes'][k]==gm['file_hashes'][k] for k in ['crates/rrrah-dedup/src/model_banks.rs','crates/rrrah-dedup/src/joint_witnesses.rs','crates/rrrah-dedup/src/model_compare.rs','crates/rrrah-dedup/src/geometry.rs'])
 runtime=D/'dedup-loftr-native-20261010-runtime-pins.json';rt=json.loads(runtime.read_text());libs={k:v for k,v in rt['pins'].items() if k.endswith('.dylib')};assert libs and all(sha(k)==v for k,v in libs.items());pins.update(libs)
 old=D/'dedup-model-bank-qualified-native-audit-20261011.json';a=json.loads(old.read_text());ref=D/'dedup-model-bank-qualified-native-20261011.json';b=json.loads(ref.read_text());previous=json.loads(b['results'][2]['stdout']);v=json.loads(r['stdout']);assert v['supported'] and v['attempts']==25 and v['pixel_window_radius']==6 and 2<=v['pixel_attempts']<=50 and v['managed_used']==0;assert v['selected_points']==989 and v['geometry_inliers']==18 and v['hypothesis_bank']==15;bits=lambda x:struct.unpack('>Q',struct.pack('>d',x))[0];assert [[bits(x) for x in row] for row in v['transform']]==[[bits(x) for x in row] for row in previous['transform']]
 counts=[tuple(map(int,x)) for x in re.findall(r'sites: (\d+), valid_sites: (\d+), informative_pairs: (\d+), agreeing_pairs: (\d+)',v['pixels'])];assert counts==[tuple(x) for x in a['results'][2]['pixel_counts']];assert all(info>=1000 and valid/sites>=.3 and agree/info>=.9 for sites,valid,info,agree in counts)
 pins.update({str(x):sha(x) for x in [p,mp,gp,runtime,old,ref,Path(__file__)]});rss=re.search(r'(\d+)\s+maximum resident set size',r['stderr']);assert rss;out=D/'dedup-model-bank-coverage-native-audit-20261011.json';assert not out.exists();out.write_text(json.dumps({'status':'verified_actual_cpu_203500_automatic_bounded_coverage','pins':pins,'radius_list':[2,6],'chosen_radius':6,'pixel_attempts':v['pixel_attempts'],'pixel_counts':counts,'selected_points':989,'witnesses':18,'elapsed_seconds':r['elapsed_seconds'],'max_rss_bytes':int(rss[1]),'managed_peak':v['managed_peak'],'scope':'Actual CPU automatic radius selection within explicit prepaid2/6 list, same H/pixels as prior fixed6 control and101-test executed core. No repeated inference per radius; no global adaptive scale/semantic precision/collection/all458/full500/RSS cap qualification.'},indent=2)+'\n');print(json.dumps({'chosen_radius':6,'pixel_attempts':v['pixel_attempts'],'counts':counts}))
if __name__=='__main__':main()
